'use strict';

var Int32Array = require( '@stdlib/array/int32' );
var Float64Array = require( '@stdlib/array/float64' );
var dsptrf = require( './../lib' );

/*
	Symmetric matrix `A` (upper triangle):

	A = [
		[  4.0,  1.0, -2.0,  2.0 ],
		[  1.0,  2.0,  0.0,  1.0 ],
		[ -2.0,  0.0,  3.0, -2.0 ],
		[  2.0,  1.0, -2.0, -1.0 ]
	]
*/

// Store the upper triangle of `A` in column-major packed form:
var AP = new Float64Array( [ 4.0, 1.0, 2.0, -2.0, 0.0, 3.0, 2.0, 1.0, -2.0, -1.0 ] ); // eslint-disable-line max-len
var IPIV = new Int32Array( 4 );

// Compute the Bunch-Kaufman factorization `A = U*D*U^T`:
var info = dsptrf( 'column-major', 'upper', 4, AP, IPIV );

console.log( AP );
console.log( IPIV );
console.log( info );
